func (t TrackpadMessage) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t TrackpadMessage) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "connected":
		return t.AsTrackpadMessageConnected()
	case "keydown":
		return t.AsTrackpadMessageKeyDown()
	case "keyup":
		return t.AsTrackpadMessageKeyUp()
	case "mouseclick":
		return t.AsTrackpadMessageMouseClick()
	case "mousedown":
		return t.AsTrackpadMessageMouseDown()
	case "mousemoverel":
		return t.AsTrackpadMessageMouseMoveRelative()
	case "mousemoveto":
		return t.AsTrackpadMessageMouseMoveTo()
	case "mousepositionupdate":
		return t.AsTrackpadMessageMousePositionUpdate()
	case "mousescroll":
		return t.AsTrackpadMessageMouseScroll()
	case "mouseup":
		return t.AsTrackpadMessageMouseUp()
	case "text":
		return t.AsTrackpadMessageText()
	case "textcontext":
		return t.AsTrackpadMessageTextContext()
	case "textedit":
		return t.AsTrackpadMessageTextEdit()
	case "textwatch":
		return t.AsTrackpadMessageTextWatch()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

