// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.CheckHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/status", wrapper.GetStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/status/agent", wrapper.GetAgentStatus)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth", wrapper.Auth)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/auth/check", wrapper.CheckAuth)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/wake", wrapper.Wake)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/monitors", wrapper.GetMonitors)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/layouts", wrapper.GetLayouts)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/layouts/switch", wrapper.SwitchLayout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/layouts/current", wrapper.GetCurrentLayout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/layouts/save-current", wrapper.SaveCurrentLayout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/layouts/remove", wrapper.RemoveLayout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/layouts/update", wrapper.UpdateLayout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/shutdown", wrapper.Shutdown)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/audio/sinks", wrapper.GetAudioSinks)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/audio/volume", wrapper.SetAudioVolume)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/monitors/brightness", wrapper.SetMonitorBrightness)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/monitors/power", wrapper.SetMonitorPower)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/monitors/power-state", wrapper.GetMonitorPowerState)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/monitors/settings", wrapper.SetMonitorSettings)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/monitors/volume", wrapper.SetMonitorVolume)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/monitors/pair", wrapper.PairMonitor)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/monitors/input", wrapper.SetMonitorInput)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/boot", wrapper.Boot)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/sim/reset", wrapper.SimReset)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/sim/state", wrapper.SimState)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/sim/set-state", wrapper.SimSetState)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/trackpad", wrapper.ConnectTrackpad)

	return m
}

